import{dispatchUpsellAccepted}from"../events";import{state}from"../store";describe("upsell store",(()=>{beforeEach((()=>{localStorage.clear(),state.upsell={id:"upsell-1"},state.product={id:"product-1",name:"LED Lantern"}})),describe("events",(()=>{it("emits scUpsellAccepted with checkout, line item, upsell and product detail",(()=>{const e=jest.fn();window.addEventListener("scUpsellAccepted",e),dispatchUpsellAccepted({id:"checkout-1",currency:"usd"},{id:"line-item-1",total_amount:16800,quantity:1}),expect(e).toBeCalledTimes(1),expect(e.mock.calls[0][0].detail).toEqual({checkout:expect.objectContaining({id:"checkout-1"}),line_item:expect.objectContaining({id:"line-item-1",total_amount:16800}),upsell:expect.objectContaining({id:"upsell-1"}),product:expect.objectContaining({id:"product-1"})}),window.removeEventListener("scUpsellAccepted",e)})),it("emits only once per upsell line item",(()=>{const e=jest.fn();window.addEventListener("scUpsellAccepted",e),dispatchUpsellAccepted({id:"checkout-1"},{id:"line-item-1"}),dispatchUpsellAccepted({id:"checkout-1"},{id:"line-item-1"}),expect(e).toBeCalledTimes(1),dispatchUpsellAccepted({id:"checkout-1"},{id:"line-item-2"}),expect(e).toBeCalledTimes(2),window.removeEventListener("scUpsellAccepted",e)})),it("does not emit without a line item id",(()=>{const e=jest.fn();window.addEventListener("scUpsellAccepted",e),dispatchUpsellAccepted({id:"checkout-1"},{}),dispatchUpsellAccepted({id:"checkout-1"},void 0),expect(e).toBeCalledTimes(0),window.removeEventListener("scUpsellAccepted",e)}))}))}));